const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),mx=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(n),id=()=>globalThis.crypto?.randomUUID?.()||String(Date.now());
const KEY='sigmatech-demo-v1';
const seed=(name,products,customers,orders)=>({company:{name,color:'#087f68',logo:''},products:products.map((p,i)=>({id:'p'+i,name:p[0],price:p[1],stock:p[2],category:p[3]})),customers:customers.map((p,i)=>({id:'c'+i,name:p[0],group:p[1],status:'Activo'})),orders:orders.map((p,i)=>({id:'o'+i,label:p[0],total:p[1],status:p[2],date:'2026-09-29',productId:null,qty:0}))});
const fresh=()=>({scenario:'negocio',spaces:{negocio:seed('Comercial Horizonte · Demo',[['Cuaderno ejecutivo',95,45,'Papelería'],['Termo acero',240,12,'Accesorios'],['Mochila urbana',590,7,'Accesorios'],['Set de bolígrafos',65,60,'Papelería']], [['Cliente ficticio 01','Frecuente'],['Cliente ficticio 02','Nuevo'],['Cliente ficticio 03','Frecuente'],['Cliente ficticio 04','Mayorista']], [['Venta 1048',780,'Completado'],['Venta 1049',590,'Pendiente'],['Venta 1050',430,'Completado'],['Venta 1051',950,'Completado']]),restaurante:seed('Mesa Verde · Demo',[['Ensalada de temporada',145,30,'Entradas'],['Pasta de la casa',190,22,'Platos fuertes'],['Agua fresca',45,40,'Bebidas'],['Postre artesanal',85,8,'Postres']], [['Comensal ficticio 01','Mesa 01'],['Comensal ficticio 02','Para llevar'],['Comensal ficticio 03','Mesa 03']], [['Pedido 201',380,'En preparación'],['Pedido 202',235,'Pendiente'],['Pedido 203',570,'Completado']]),escuela:seed('Instituto Aurora · Demo',[['Taller de lectura',0,25,'Grupo A'],['Laboratorio creativo',0,20,'Grupo B'],['Club de ciencias',0,15,'Grupo C']], [['Alumno ficticio 01','Grupo A'],['Alumno ficticio 02','Grupo B'],['Alumno ficticio 03','Grupo A'],['Alumno ficticio 04','Grupo C']], [['Seguimiento 01',0,'Pendiente'],['Seguimiento 02',0,'En preparación'],['Seguimiento 03',0,'Completado']])}});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state?.spaces?.negocio)throw Error()}catch{state=fresh()}let view='dashboard';
const space=()=>state.spaces[state.scenario],school=()=>state.scenario==='escuela',restaurant=()=>state.scenario==='restaurante';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('No se pudo guardar: almacenamiento lleno o deshabilitado.')}render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function labels(){return{customers:school()?'Alumnos':'Clientes',products:school()?'Grupos':restaurant()?'Menú':'Productos',orders:school()?'Seguimiento':restaurant()?'Pedidos':'Ventas',inventory:school()?'Cupos':'Inventario'}}
const svgIcon=paths=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const icons={dashboard:svgIcon('<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>'),customers:svgIcon('<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>'),products:svgIcon('<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v9l9 5 9-5V8M12 13v9M7 5.8l9 5"/>'),orders:svgIcon('<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v3H9zM9 11h6M9 15h6"/>'),inventory:svgIcon('<path d="M3 10V6l9-3 9 3v4M3 10h18v11H3zM8 14h8v7M3 6l9 3 9-3"/>'),reports:svgIcon('<path d="M4 3v18h17M8 16v-5M13 16V7M18 16v-8"/>'),scenarios:svgIcon('<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 10h18M10 10v11"/>'),config:svgIcon('<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>')};
function header(title,description,action=''){return `<div class="top"><div><div class="eyebrow">${esc(space().company.name)}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function pill(status){return `<span class="pill ${status==='Pendiente'?'warn':status==='En preparación'?'gray':''}">${esc(status)}</span>`}
function bars(){const rows=space().orders.slice(-6);return `<div class="chart">${rows.map((o,i)=>{const value=school()?(o.status==='Completado'?100:o.status==='En preparación'?50:20):o.total,max=school()?100:Math.max(...rows.map(x=>x.total),1);return `<div class="barwrap"><small>${school()?value+'%':mx(value)}</small><div class="bar" style="height:${Math.max(5,value/max*100)}%"></div><span>${i+1}</span></div>`}).join('')}</div>`}
function dashboard(){const s=space(),l=labels(),done=s.orders.filter(o=>o.status==='Completado'),total=done.reduce((a,o)=>a+o.total,0),low=s.products.filter(p=>p.stock<10).length;return header('Resumen de operación','Una vista de los registros de este escenario.',`<button data-add="orders">${school()?'Nuevo seguimiento':restaurant()?'Nuevo pedido':'Nueva venta'}</button>`)+`<div class="stats"><div class="stat"><label>${school()?'Seguimientos completos':'Ventas completadas'}</label><strong>${school()?done.length:mx(total)}</strong><small>Datos de demostración</small></div><div class="stat"><label>${l.orders} registrados</label><strong>${s.orders.length}</strong><small>${s.orders.filter(o=>o.status!=='Completado').length} pendientes de completar</small></div><div class="stat"><label>${l.customers}</label><strong>${s.customers.length}</strong><small>Registros ficticios</small></div><div class="stat"><label>${school()?'Grupos con pocos cupos':'Productos con stock bajo'}</label><strong>${low}</strong><small>Menos de 10 unidades</small></div></div><div class="grid"><section class="card"><h2>${school()?'Avance de seguimientos':'Importe de las últimas operaciones'}</h2><p>${school()?'Indicador ilustrativo según el estado.':'Importes registrados, incluidos pendientes.'}</p>${bars()}<div class="row"><span>Consulta el detalle de cada registro</span><a href="#reports" style="color:var(--accent)">Ver reportes</a></div></section><section class="card"><h2>Actividad reciente</h2>${s.orders.slice(-4).reverse().map(o=>`<div class="row"><span>${esc(o.label)}<small style="display:block;color:var(--muted);margin-top:6px">${school()?esc(o.date):mx(o.total)}</small></span>${pill(o.status)}</div>`).join('')}<p>Los cambios de esta demo no se sincronizan con otros dispositivos.</p></section></div>${dashboardDetails()}`}
function dashboardDetails(){const s=space(),completed=s.orders.filter(o=>o.status==='Completado').length,ratio=s.orders.length?Math.round(completed/s.orders.length*100):0,attention=[...s.products].sort((a,b)=>a.stock-b.stock).slice(0,3);return `<div class="lower-grid"><section class="card"><h2>${school()?'Seguimientos resueltos':'Operaciones completadas'}</h2><div class="completion"><div class="ring"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="ring-track" cx="50" cy="50" r="42"/><circle class="ring-value" cx="50" cy="50" r="42" stroke-dasharray="${ratio*2.64} 264"/></svg><strong>${ratio}%</strong></div><div><strong>${completed} de ${s.orders.length} registros</strong><p>Calculado con el estado actual de esta demo.</p><a class="cardlink" href="#orders">Revisar ${labels().orders.toLowerCase()}</a></div></div></section><section class="card"><h2>${school()?'Disponibilidad de grupos':'Existencias por revisar'}</h2>${attention.map(p=>`<div class="stockline"><span>${esc(p.name)}</span><span class="pill ${p.stock<10?'warn':'gray'}">${p.stock} ${school()?'cupos':'unidades'}</span></div>`).join('')}<a class="cardlink" href="#inventory">Abrir ${labels().inventory.toLowerCase()}</a></section></div>`}

function list(kind){const s=space(),l=labels(),items=s[kind];let heads,rows;
if(kind==='customers'){heads=['Registro',school()?'Grupo':'Segmento','Estado','Acciones'];rows=items.map(x=>`<tr data-search="${esc(x.name.toLowerCase())}"><td><strong>${esc(x.name)}</strong></td><td>${esc(x.group)}</td><td>${pill(x.status)}</td><td><button class="tableaction" data-edit="customers:${x.id}">Editar</button><button class="tableaction delete" data-delete="customers:${x.id}">Eliminar</button></td></tr>`)}
if(kind==='products'){heads=[school()?'Grupo':'Producto',school()?'Área':'Categoría',...(school()?[]:['Precio MXN']),school()?'Cupos':'Stock','Acciones'];rows=items.map(x=>`<tr data-search="${esc(x.name.toLowerCase())}"><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td>${school()?'':`<td class="money">${mx(x.price)}</td>`}<td>${x.stock}</td><td><button class="tableaction" data-edit="products:${x.id}">Editar</button><button class="tableaction delete" data-delete="products:${x.id}">Eliminar</button></td></tr>`)}
if(kind==='orders'){heads=['Registro','Fecha',...(school()?[]:['Importe MXN']),'Estado','Acciones'];rows=items.map(x=>`<tr data-search="${esc(x.label.toLowerCase())}"><td><strong>${esc(x.label)}</strong></td><td>${esc(x.date)}</td>${school()?'':`<td class="money">${mx(x.total)}</td>`}<td>${pill(x.status)}</td><td><button class="tableaction" data-status="${x.id}">Cambiar estado</button></td></tr>`)}
return header(l[kind],school()?'Registros ficticios para demostrar el flujo escolar.':'Administra los registros de este escenario.',`<button data-add="${kind}">Añadir ${kind==='orders'?school()?'seguimiento':restaurant()?'pedido':'venta':kind==='products'?school()?'grupo':'producto':school()?'alumno':'cliente'}</button>`)+`<section class="card"><input class="search" id="search" placeholder="Buscar por nombre" aria-label="Buscar registros"><div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="5" class="empty">No hay registros. Añade uno para comenzar.</td></tr>`}</tbody></table></div></section>`}
function inventory(){return header(labels().inventory,school()?'Capacidad ilustrativa por grupo.':'Existencias locales; los nuevos pedidos descuentan unidades.')+`<section class="card"><div class="tablewrap"><table><thead><tr><th>${school()?'Grupo':'Producto'}</th><th>${school()?'Cupos disponibles':'Existencias'}</th><th>Situación</th><th>Ajuste</th></tr></thead><tbody>${space().products.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stock}</td><td>${pill(p.stock<10?'Pendiente':'Activo')}</td><td><button class="tableaction" data-stock="${p.id}:-1" ${p.stock===0?'disabled':''}>−1</button><button class="tableaction" data-stock="${p.id}:1">+1</button></td></tr>`).join('')}</tbody></table></div></section>`}
function reports(){const s=space(),all=s.orders.reduce((a,o)=>a+o.total,0),done=s.orders.filter(o=>o.status==='Completado'),sum=done.reduce((a,o)=>a+o.total,0);return header('Reportes','Resumen calculado con los registros actuales.',`<button id="export">Descargar CSV</button>`)+`<div class="grid"><section class="card"><h2>${school()?'Avance de seguimiento':'Operaciones registradas'}</h2>${bars()}<p>${school()?'El porcentaje del gráfico representa un estado ilustrativo, no una evaluación académica.':'El gráfico muestra los últimos importes ingresados; no representa una tendencia histórica.'}</p></section><section class="card"><h2>Resumen</h2><div class="row"><span>Total de registros</span><strong>${s.orders.length}</strong></div><div class="row"><span>Completados</span><strong>${done.length}</strong></div><div class="row"><span>${school()?'Avance':'Importe completado'}</span><strong>${school()?(s.orders.length?Math.round(done.length/s.orders.length*100):0)+'%':mx(sum)}</strong></div>${school()?'':`<div class="row"><span>Importe total registrado</span><strong>${mx(all)}</strong></div>`}<p>Reporte ilustrativo. No incluye impuestos, costos ni utilidad.</p></section></div>`}
function scenarios(){return header('Una base, tres escenarios','Cambia el contexto para explorar cada adaptación.')+`<div class="cards">${[['negocio','Negocio general','Clientes, productos, ventas e inventario.'],['restaurante','Restaurante','Menú, comensales, pedidos y estados de preparación.'],['escuela','Escuela','Grupos, alumnos ficticios y seguimiento administrativo.']].map(([key,name,text])=>`<section class="card scenarioCard"><div class="eyebrow">${key===state.scenario?'ESCENARIO ACTUAL':'ADAPTACIÓN DEMOSTRATIVA'}</div><h2>${name}</h2><p>${text}</p><button data-scenario="${key}">Abrir escenario</button></section>`).join('')}</div><p class="notice" style="margin-top:25px">Cada escenario conserva sus cambios localmente. Esta separación visual no equivale a aislamiento seguro entre empresas.</p>`}
function config(){const c=space().company;return header('Configuración de empresa','Personaliza este escenario para una demostración.')+`<section class="card settings"><form id="settings"><label for="name">Nombre de la empresa</label><input id="name" name="name" maxlength="70" required value="${esc(c.name)}"><label for="color">Color de acento</label><input id="color" name="color" type="color" value="${esc(c.color)}"><label for="logoFile">Logotipo (PNG, JPEG o WebP, máximo 300 KB)</label><input id="logoFile" name="logoFile" type="file" accept="image/png,image/jpeg,image/webp"><small>La imagen se guarda solo en este navegador. Usa un archivo autorizado.</small><div class="actions"><button>Guardar personalización</button><button class="secondary" type="button" id="removeLogo">Quitar logotipo</button></div></form><div class="row" style="margin-top:25px"><div><strong>Restablecer demo</strong><p>Borra todos los cambios locales de los tres escenarios.</p></div><button class="danger" id="reset">Restablecer</button></div></section>`}
function render(){const l=labels();$('#scenario').value=state.scenario;document.documentElement.style.setProperty('--accent',space().company.color);const hex=space().company.color.slice(1),lum=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)).reduce((a,v,i)=>a+v*[.299,.587,.114][i],0);document.documentElement.style.setProperty('--accent-ink',lum>155?'#092d23':'#ffffff');$('#companyName').textContent=space().company.name;$('#logo').hidden=!space().company.logo;$('#logo').src=space().company.logo||'';const nav=[['dashboard','Resumen'],['customers',l.customers],['products',l.products],['orders',l.orders],['inventory',l.inventory],['reports','Reportes'],['scenarios','Escenarios'],['config','Configuración']];$('#nav').innerHTML=nav.map(([v,n])=>`<a href="#${v}" class="${v===view?'active':''}" ${v===view?'aria-current="page"':''}><span class="glyph" aria-hidden="true">${icons[v]}</span>${n}</a>`).join('');$('#main').innerHTML=({dashboard,customers:()=>list('customers'),products:()=>list('products'),orders:()=>list('orders'),inventory,reports,scenarios,config}[view]||dashboard)();document.querySelectorAll('.stat').forEach((el,i)=>{const icon=document.createElement('span');icon.className='stat-symbol';icon.innerHTML=icons[['reports','orders','customers','inventory'][i]];el.appendChild(icon)});bind()}
function field(name,label,type='text',value='',options){return `<label for="f-${name}">${label}</label>${options?`<select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="'+(name==='price'?'0.01':'1')+'"':'maxlength="80"'} required>`}`}
function openForm(kind,editId){const x=editId?space()[kind].find(x=>x.id===editId):null;$('#dialogTitle').textContent=(x?'Editar ':'Añadir ')+labels()[kind].toLowerCase();let fields='';if(kind==='customers')fields=field('name',school()?'Identificador ficticio de alumno':'Nombre ficticio', 'text',x?.name)+field('group',school()?'Grupo':'Segmento','text',x?.group);if(kind==='products')fields=field('name',school()?'Nombre del grupo':'Nombre del producto','text',x?.name)+field('category',school()?'Área':'Categoría','text',x?.category)+(school()?'':field('price','Precio MXN','number',x?.price||0))+field('stock',school()?'Cupos disponibles':'Existencias','number',x?.stock||0);if(kind==='orders'){fields=field('label',school()?'Nombre del seguimiento':'Referencia del pedido','text','')+field('date','Fecha','date',new Date().toISOString().slice(0,10));if(!school())fields+=field('productId','Producto','text','',space().products.map(p=>[p.id,`${p.name} · ${mx(p.price)} · ${p.stock} disponibles`]))+field('qty','Cantidad','number',1);fields+=field('status','Estado','text','Pendiente',['Pendiente','En preparación','Completado'].map(t=>[t,t]))}$('#fields').innerHTML=fields;$('#form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(kind==='orders'){let total=0;if(!school()){const product=space().products.find(p=>p.id===data.productId),qty=Number(data.qty);if(!product||!Number.isInteger(qty)||qty<1||qty>product.stock){toast('Revisa el producto, la cantidad y las existencias.');return}product.stock-=qty;total=Math.round(product.price*qty*100)/100;}space().orders.push({...data,id:id(),total,qty:Number(data.qty||0)})}else{if(kind==='products'){data.price=Number(data.price||0);data.stock=Number(data.stock);if(!Number.isInteger(data.stock)||data.stock<0||!Number.isFinite(data.price)||data.price<0)return toast('Revisa precio y existencias.')}if(x)Object.assign(x,data);else space()[kind].push({...data,id:id(),status:'Activo'})}$('#dialog').close();save();toast('Registro guardado en la demo local.');};$('#dialog').showModal()}
function changeScenario(key){if(!state.spaces[key])throw Error('Escenario inválido');state.scenario=key;view='dashboard';location.hash='dashboard';save()}
function bind(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(...b.dataset.edit.split(':')));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const[k,key]=b.dataset.delete.split(':');if(confirm('¿Eliminar este registro ficticio?')){space()[k]=space()[k].filter(x=>x.id!==key);save();toast('Registro eliminado.')}});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const x=space().orders.find(o=>o.id===b.dataset.status),values=['Pendiente','En preparación','Completado'];x.status=values[(values.indexOf(x.status)+1)%3];save();toast('Estado actualizado.');});document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>{const[key,delta]=b.dataset.stock.split(':');const p=space().products.find(x=>x.id===key);p.stock=Math.max(0,p.stock+Number(delta));save()});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>changeScenario(b.dataset.scenario));if($('#search'))$('#search').oninput=e=>document.querySelectorAll('[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase()));if($('#export'))$('#export').onclick=()=>{const cell=x=>`"${String(x).replace(/^[=+@-]/,"'$&").replaceAll('"','""')}"`,rows=[['Registro','Fecha','Importe MXN','Estado'],...space().orders.map(o=>[o.label,o.date,o.total,o.status])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`sigma-${state.scenario}-demo.csv`;a.click();URL.revokeObjectURL(url)};if($('#settings')){$('#settings').onsubmit=async e=>{e.preventDefault();const color=$('#color').value;if(!/^#[0-9a-f]{6}$/i.test(color))return;const c=space().company,file=$('#logoFile').files[0];if(file){if(file.size>300000||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Usa PNG, JPEG o WebP de menos de 300 KB.');c.logo=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}c.name=$('#name').value.trim();c.color=color;save();toast('Identidad actualizada.');};$('#removeLogo').onclick=()=>{space().company.logo='';save()};$('#reset').onclick=()=>{if(confirm('¿Restablecer todos los datos de la demo?')){state=fresh();view='dashboard';location.hash='dashboard';save();toast('Demo restablecida.')}}}}
$('#scenario').onchange=e=>changeScenario(e.target.value);$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#nav').onclick=()=>$('#sidebar').classList.remove('open');$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();window.onhashchange=()=>{view=location.hash.slice(1)||'dashboard';render()};view=location.hash.slice(1)||'dashboard';render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_demo_scenario',description:'Abrir un escenario demostrativo local de SigmaTech.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['negocio','restaurante','escuela']}},required:['scenario'],additionalProperties:false},execute:input=>{changeScenario(input.scenario);return{scenario:state.scenario}},annotations:{readOnlyHint:false}})}catch{}}

// Preferencia visual local: no afecta los datos de los escenarios.
try{document.body.classList.toggle('dark',localStorage.getItem('sigma-theme')==='dark')}catch{}
const themeButton=document.createElement('button');themeButton.type='button';themeButton.className='iconbtn';themeButton.setAttribute('aria-label','Alternar tema claro y oscuro');themeButton.title='Tema claro / oscuro';themeButton.innerHTML=svgIcon('<path d="M20.5 13a8.5 8.5 0 0 1-9.5-9.5A8.5 8.5 0 1 0 20.5 13Z"/>');themeButton.onclick=()=>{const dark=document.body.classList.toggle('dark');try{localStorage.setItem('sigma-theme',dark?'dark':'light')}catch{}themeButton.setAttribute('aria-pressed',String(dark))};document.querySelector('.header-right').prepend(themeButton);
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open')});
